const a={meta:{title:"POP · Il SaaS dei creator UEFN"},nav:{features:"Funzionalità",pricing:"Prezzi",faq:"FAQ",login:"Accedi",join:"Entra nella beta",home:"POP, home",lang:"Lingua",search:"Cerca un paese"},menu:{groups:["Organizzarsi","Collegare UEFN","Far crescere la mappa"],items:[{t:"Attività e pianificazione",d:"Attività da un’ora, traguardi e ritardi seguiti."},{t:"Pagine",d:"Documenti, regole e database della mappa."},{t:"Lavagna",d:"Note, forme e frecce, insieme in tempo reale."},{t:"Team e ruoli",d:"Invita, assegna un ruolo, ognuno sa cosa fare."},{t:"Organizer",d:"Gli attori del livello ordinati e modificati in blocco."},{t:"UEFN Link",d:"I tuoi progetti UEFN sincronizzati con POP."},{t:"IA collegate",d:"Claude, Cursor o Codex portano avanti le tue attività."},{t:"POP Forge",d:"L’app desktop che costruisce in UEFN."},{t:"Analisi di mercato",d:"I generi che attirano e quelli saturi."},{t:"Tendenze video",d:"Cosa va forte su TikTok e YouTube Shorts."},{t:"Playtest e lancio",d:"Fai testare la mappa e prepara l’uscita."},{t:"Pagamenti",d:"Divisione dei guadagni e resoconto di ognuno."}],bottom:["Discord e GitHub collegati","Su Mac e PC"],all:"Tutte le funzioni"},hero:{announce:"Beta privata aperta ai creator UEFN",h1a:"Crea su UEFN.",h1b:"Da solo o in team, senza caos.",subA:"POP è il SaaS che aiuta i creator UEFN dall’idea all’uscita: ",subB:"task da un’ora",subC:", lavagna, IA collegate, analisi di mercato e divisione dei guadagni.",cta:"Entra nella lista d’attesa",see:"Scopri le funzionalità",micro1:"Beta privata",micro2:"Accesso su lista d’attesa",micro3:"Collegato a UEFN"},marquee:{label:"Funziona con i tuoi strumenti",epic:"API Fortnite di Epic"},pain:{eyebrow:"Il problema",h2a:"Discord, Google Docs, file ovunque…",h2b:"e la mappa non avanza.",without:"Senza POP",with:"Con POP",bad:["«Chi ha toccato lo spawner?»","Le idee si perdono su Discord","Una lista di task in un Google Doc","Il foglio dei guadagni, versione 7","«Quando usciamo, già?»","Costruire senza sapere se il genere funziona"],good:["Ogni azione è tracciata e annullabile","Le idee della lavagna diventano attività","Task da un’ora, con dipendenze","Un estratto chiaro per ognuno","Traguardi e ritardi seguiti automaticamente","Un verdetto per genere, con dati reali"]},feat:{eyebrow:"Funzionalità",h2:"Tutto per creare su UEFN, dall’idea al giorno del lancio.",p:"Quelle che vedi qui sono le vere schermate di POP, semplificate.",items:[{tag:"Attività e pianificazione",h:"Attività da un’ora. Una pianificazione che regge.",p:"Il generatore divide la mappa in attività da un’ora con le loro dipendenze. La pianificazione segue i traguardi e segnala i ritardi, e un assistente integrato riassume la giornata.",pts:["Kanban e dipendenze","Traguardi e ritardi seguiti","Riepilogo del giorno"]},{tag:"Organizer",h:"Tutti i tuoi dispositivi. In ordine in tre secondi.",p:"Cerca per tag, tipo o cartella, selezionane venti e rinominali, spostali o duplicali in un colpo. Ctrl+Z annulla. Se UEFN è chiuso, le modifiche aspettano.",pts:["Ricerca tag:, type:, cartella:","Modifiche in blocco","Tutto è annullabile"]},{tag:"Lavagna",h:"Disegnate la mappa insieme.",p:"Post-it, forme, frecce, colori, grassetto, sottolineato: tutto per mettere giù le idee. Votate e trasformate i post-it migliori in task.",pts:["Formattazione completa","Tempo reale in squadra","Post-it → task"]},{tag:"Analisi",h:"Sappi cosa costruire prima di costruire.",p:"Quali generi attirano i giocatori, dove c’è spazio, quali mappe decollano al lancio e cosa va forte nei video. Dati dall’API ufficiale di Epic.",pts:["Verdetto per genere","Mappe che funzionano","Trend TikTok e Shorts"]},{tag:"Pagamenti",h:"Ognuno sa quanto guadagna.",p:"Regole di divisione a percentuale, fisse o per task, import dei guadagni, estratto per persona. Basta fogli di calcolo persi su Discord.",pts:["Percentuale, fisso, per task","Import CSV","Estratto di ognuno"]}],aiB:"Usi già un’IA?",aiText:"Collega Claude, Cursor, Codex o un’altra IA compatibile MCP: prende un task, scrive il Verse, compila e chiude il task con una nota. Ogni azione è registrata e annullabile. Compatibili: Claude Code, Claude Desktop, Cursor, Codex, Windsurf, VS Code (GitHub Copilot), Gemini CLI."},stats:[["1 h","per task, per avanzare ogni giorno"],["0","servizi IA esterni obbligatori"],["7 giorni","di statistiche per mappa, dall’API di Epic"],["100%","delle azioni UEFN annullabili"]],pricing:{eyebrow:"Prezzi",h2:"Scegli il tuo piano.",p:"POP è in beta privata: l’accesso avviene tramite lista d’attesa. All’apertura, ogni account parte con 7 giorni di prova gratuita di Pro, senza carta.",perMonth:"/ mese",compare:"Confronta i piani",unlimited:"Illimitato",soon:"Presto",plans:[{name:"Starter",tag:"Per creare",desc:"Tutto lo spazio di lavoro per creare le tue mappe, da solo o in team.",cta:"Entra nella lista"},{name:"Pro",tag:"Il più completo",desc:"Tutto Starter, più l’analisi: idee di mappe, mercato, monitoraggio di Discover.",cta:"Entra nella lista"}],rows:["Organizzazione","Task da un’ora, Kanban, dipendenze","Assistente integrato (riepilogo del giorno, ritardi)","Pagine, lavagna, pianificazione e milestone","Mappe","Membri","UEFN","UEFN Link: progetti sincronizzati","Organizer degli attori e modifiche in blocco","IA collegate (Claude, Cursor, Codex…)","POP Forge: costruzione assistita in UEFN","Crescita","Idee di mappe, analisi del mercato, monitoraggio di Discover","Trend video TikTok e YouTube Shorts","Scambio di playtest e giorno del lancio","Divisione dei guadagni ed estratti","Discord, GitHub, Lore"],perDay:["Meno di 0,50 € al giorno","Meno di 1 € al giorno"],hints:["","La mappa divisa in attività da un’ora, con cosa blocca cosa","Ogni mattina: cosa è in ritardo e da dove iniziare","La documentazione della mappa, le idee dal vivo e il calendario","Tutte le mappe che vuoi","Invita tutto il team senza costi extra","","Le tue IA vedono il vero progetto UEFN: attori e Verse","","Collega la tua IA via MCP; ogni azione è annullabile","Costruire in UEFN partendo da una richiesta","","I generi che attirano giocatori e dove c’è ancora spazio","Cosa sta salendo ora su TikTok e YouTube Shorts","Trova tester e prepara il giorno del lancio","Chi riceve quanto, con un rendiconto per ciascuno","Notifiche e collegamenti ai tuoi strumenti"]},faq:{eyebrow:"FAQ",h2:"Le domande che ci fanno.",items:[["Serve un PC Windows?","Per collegare UEFN, sì: UEFN funziona solo su Windows e UEFN Link gira su quel PC. Il resto di POP funziona in qualsiasi browser, Mac compreso."],["POP pubblica la mia mappa?","No. POP prepara tutto (verifica prima della pubblicazione, playtest, piano del giorno del lancio), ma la pubblicazione avviene sempre nel portale creator di Epic."],["POP funziona se creo da solo?","Sì. POP è pensato sia per chi crea da solo sia per i team, già dal piano Starter: puoi invitare membri più tardi senza cambiare nulla."],["Quali IA posso collegare?","Quelle che supportano i server MCP: Claude Code, Claude Desktop, Cursor, Codex, Windsurf, VS Code (GitHub Copilot), Gemini CLI. Claude Desktop richiede che POP sia online in HTTPS. L’abbonamento alla tua IA non è incluso in POP. Le IA di chat nel browser (ChatGPT, Gemini, Copilot sul web) per ora non sono supportate. Una volta collegata in «IA collegate», la tua IA legge e modifica le attività e gli attori UEFN, scrive il Verse, e ogni azione è registrata e annullabile."],["Da dove vengono i dati dell’analisi?","Dall’API ufficiale Fortnite di Epic: giocatori, picco di giocatori simultanei, tempo di gioco e retention di ogni mappa pubblica, su 7 giorni."],["Come ottengo l’accesso?","POP è in beta privata. Iscriviti alla lista d’attesa: valutiamo le richieste una per una, poi ti inviamo il tuo nome utente e una password provvisoria, da cambiare al primo accesso."],["Quanto costa?","I prezzi sono indicati sopra. Valgono dal lancio di POP; i membri della beta vengono avvisati prima di qualsiasi pagamento."]]},final:{h2a:"La tua prossima mappa",h2b:"inizia qui.",p:"Entra nella lista d’attesa: ti inviamo l’accesso appena si libera un posto."},foot:{legalTitle:"Note legali",made:"Fatto da creator Fortnite, per creator Fortnite.",legal:"Fortnite e UEFN sono marchi di Epic Games. POP non è affiliato né approvato da Epic Games.",product:"Prodotto",help:"Aiuto",account:"Account"},mock:{overview:"Panoramica",nav:["Panoramica","Pagine","Lavagna","Task","Organizer","Mercato"],hello:"Ciao Léa, ti propongo di iniziare dal #42.",late:"2 task in ritardo (il più vecchio era previsto per il 12 nov.).",mile:"Milestone «Beta» tra 5 giorni: mancano 9 task, ritardo previsto di 1 giorno.",take:"Prendi",start:"Inizia",unlocks:"sblocca altri 3 task",today:"previsto oggi",waits:"attende #42",todo:"Da fare",doing:"In corso",done:"Fatto",tasks:["Sistema di punteggio","Scenografia zona 2","Schermata finale","Playtest interno","Spawn dei giocatori","Tempesta"],sent:"inviato a UEFN",err:"Riga 12: int e float non si possono sommare.",fix:"Correggi: Points += 1",red:"Squadra rossa",selected:"2 selezionati",rename:"Rinomina",move:"Sposta",dup:"Duplica",s1:"Modalità squadre 4v4",s2a:"Boss finale",s2b:"al centro",s3:"Economia: 1 moneta / eliminazione",verdicts:["Buona opportunità","Popolare ma conteso","Saturo","Nicchia"],typical:"giocatori / mappa tipica",earnings:"Guadagni di ottobre",roles:["Codice · 40%","Mappa · 35%","Musica · fisso","Resto"],noTransfer:"POP calcola, non fa alcun bonifico."},wl:{eyebrow:"Beta privata",title:"Entra nella lista d’attesa",intro:"Apriamo POP poco alla volta per seguire ogni creator. Dicci chi sei e ti invieremo l’accesso il prima possibile.",pageIntro:"Durante la beta gli account POP vengono creati dal team. Dicci chi sei: appena il tuo accesso è approvato, ricevi il tuo nome utente e una password provvisoria.",invalid:"Questo link di accesso non è valido, è già stato usato o è scaduto. Fai una nuova richiesta o scrivi al team POP.",name:"Nome o nickname",email:"E-mail",studio:"Studio",optional:"(facoltativo)",studioPh:"Nome dello studio",team:"Dimensione del team",teams:["Da solo","Da 2 a 3","Da 4 a 10","Più di 10"],exp:"Esperienza",exps:["Principiante UEFN","Alcune mappe pubblicate","Creator esperto","Studio professionale"],links:"Le tue mappe o i tuoi social",linksPh:"Codici isola, TikTok, YouTube…",msg:"Cosa vuoi fare con POP",msgPh:"Es.: siamo in 4 su una mappa tycoon e ci perdiamo tra Discord e i Google Docs.",send:"Richiedi l’accesso",sending:"Invio…",nospam:"Niente spam: ti scriviamo solo per darti l’accesso.",privacy:"Informativa sulla privacy",okTitle:"Fatto, grazie!",okText:"Riceverai un’e-mail all’indirizzo indicato appena il tuo accesso sarà pronto, con un link per attivare l’account. Controlla anche lo spam.",alreadyTitle:"Sei già nella lista.",approvedTitle:"Il tuo accesso è già approvato.",approvedText:"Il tuo account è pronto: hai ricevuto un’e-mail con un link per attivarlo e scegliere la password. Controlla anche lo spam.",close:"Chiudi"}};export{a as default};
